MATCH (p:LegalEntity) WHERE p.group_limit IS NOT NULL AND NOT EXISTS { (p)-[:OWNED_BY {control: true}]->() }
                         CALL (p) { MATCH (p)<-[:OWNED_BY*0.. {control: true}]-(m:LegalEntity) RETURN collect(DISTINCT m) AS ms }
                         RETURN p.id AS ultimate_parent, p.name AS name, p.group_limit AS group_limit,
                                [m IN ms | m.id] AS member_entity_ids,
                                [m IN ms WHERE m.cif_no IS NOT NULL | m.cif_no] AS member_cif_nos ORDER BY name

MATCH (start:LegalEntity) WHERE start.id = $e OR toLower(start.name) STARTS WITH toLower($e)
WITH start ORDER BY start.id LIMIT 1
MATCH p = (start)-[:OWNED_BY*0.. {control: true}]->(top:LegalEntity) WHERE NOT EXISTS { (top)-[:OWNED_BY {control: true}]->() }
WITH start, top ORDER BY length(p) DESC LIMIT 1
CALL (top) {
  MATCH path = (m:LegalEntity)-[:OWNED_BY*0.. {control: true}]->(top)
  WITH m, min(length(path)) AS depth
  RETURN collect({entity_id: m.id, name: m.name, type: m.type, depth: depth, cif_no: m.cif_no}) AS members
}
WITH start, top, members, [x IN members | x.entity_id] AS ids
CALL (ids) {
  UNWIND ids AS id MATCH (:LegalEntity {id: id})<-[r:OWNED_BY]-(j:LegalEntity) WHERE NOT r.control
  RETURN collect({entity_id: j.id, name: j.name, cif_no: j.cif_no, owner: id, pct: r.pct, reason: 'minority stake, not controlled'}) AS minority
}
CALL (ids) {
  UNWIND ids AS id MATCH (:LegalEntity {id: id})<-[r:WAS_OWNED_BY]-(s:LegalEntity)
  OPTIONAL MATCH (s)-[:OWNED_BY]->(now:LegalEntity)
  RETURN collect({entity_id: s.id, name: s.name, cif_no: s.cif_no, former_owner: id, ownership_ended: toString(r.eff_to),
                  current_owner: now.name, reason: 'sold / ownership ended'}) AS former
}
CALL (ids) {
  UNWIND ids AS id MATCH (f:Facility)-[:BORROWED_BY]->(:LegalEntity {id: id}) WHERE f.status = 'ACTIVE'
  RETURN collect({facility_id: f.id, borrower: id, product: f.product}) AS facilities
}
CALL (ids) {
  UNWIND ids AS id MATCH (g:LegalEntity)-[x:GUARANTEES]->(f:Facility)-[:BORROWED_BY]->(:LegalEntity {id: id})
  RETURN collect({guarantee_id: x.id, facility_id: f.id, borrower: id, guarantor: g.id, guarantor_name: g.name,
                  guarantor_in_group: g.id IN ids, amount: x.amount, status: x.status, expires: toString(x.exp_dt),
                  guarantor_rating_agy1: g.rating_agy1}) AS guarantees
}
RETURN start.id AS requested, top {.id, .name, .rating_agy1, rating_agy1_dt: toString(top.rating_agy1_dt), .outlook_agy1,
       .rating_agy2, rating_agy2_dt: toString(top.rating_agy2_dt), .group_limit} AS ultimate_parent,
       members, minority, former, facilities, guarantees

